from h import *
P='bio'
U='진핵생물 발현 조절'
R1=['b8n:1'];R2=['b8n:2'];R3=['b8n:3']
E('b8n03',P,U,'태아의 헤모글로빈(HbF)이 성인의 헤모글로빈(HbA)과 달라야 하는 이유를 쓰시오. [3점]',['태아는 모체의 태반 혈액에서 산소를 받음','성인 Hb보다 산소 친화도가 큰 Hb 필요','같은 Hb면 태아에게 산소 공급이 어려움'],'태아는 엄마의 혈액(태반)에서 산소를 받아야 하므로 성인보다 산소 친화도가 큰 헤모글로빈이 필요하다. 같은 헤모글로빈이면 태아에게 산소가 잘 넘어가지 않는다.',R1)
E('b8n11',P,U,'어미 쥐가 새끼를 많이 핥아 준 경우와 그렇지 않은 경우, 새끼의 스트레스 반응이 다르게 나타난다. GR 유전자를 이용해 그 원리를 설명하시오. [4점]',['핥아 줌 → GR 유전자 프로모터 메틸화 X → GR 전사 O','GR(스트레스 호르몬 수용체) 많음 → 스트레스 호르몬 조절 잘 됨 → 스트레스↓','안 핥음 → 프로모터 메틸화 → GR 전사 X → 스트레스↑','DNA 서열 변화 없이 환경이 발현을 바꿈(후성유전)'],'많이 핥아 준 새끼는 GR 유전자 프로모터가 메틸화되지 않아 GR이 전사되고, 스트레스 호르몬이 잘 조절되어 스트레스가 적다. 핥아 주지 않으면 프로모터가 메틸화되어 GR이 전사되지 않아 스트레스에 취약하다. 염기서열이 아닌 환경에 의한 후성유전적 변화이다.',R1)
E('b8n15',P,U,'체세포 핵치환으로 만든 복제 동물은 성공률이 낮고 일찍 죽거나 조기 노화가 나타나는 경우가 많다. 그 이유를 쓰시오. [3점]',['체세포 핵에 남은 메틸화 등 후성유전적 표지','난자 세포질에 의해 완전히 새것으로 지워지지 않음','발현되어야 할 유전자 발현 이상 → 발생 이상·조기 노화'],'체세포의 메틸화 표지(후성유전적 표지)가 난자의 세포질에 의해 완전히 새것으로 지워지지 않아, 발생에 필요한 유전자 발현이 제대로 일어나지 않기 때문이다.',R2+R3)
M('b8n26',P,U,2,'자유 리보솜과 부착 리보솜(거친면 소포체)에 대한 설명으로 옳은 것은?',
 [('구성은 같으며, 번역 중인 단백질에 신호 펩타이드가 있어 SRP가 결합하면 소포체에 붙는다','어디서 일하느냐는 만드는 단백질이 결정'),('부착 리보솜은 자유 리보솜과 구성 성분이 다르다','구성은 같아요.'),('부착 리보솜은 처음부터 소포체에서 번역을 시작한다','번역은 세포질에서 시작돼요.'),('SRP는 소포체 막을 구성하는 지질이다','RNA–단백질 입자예요.')],'',R2)

M('b8n01',P,U,1,'간세포는 알부민, 수정체 세포는 크리스탈린을 발현하는 것과, 헤모글로빈이 태아 α₂γ₂에서 성인 α₂β₂로 바뀌는 것을 각각 바르게 짝지은 것은?',
 [('공간적 조절 – 시간적 조절','장소(세포)에 따라 / 발생 시기에 따라'),('시간적 조절 – 공간적 조절','반대예요.'),('공간적 조절 – 공간적 조절','헤모글로빈은 시기에 따른 변화예요.'),('번역 후 조절 – 선택적 스플라이싱','둘 다 전사 수준의 공간·시간적 조절이에요.')],'',R1+['bio8:2','bio8:3'])
M('b8n04',P,U,2,'번역 전 조절의 예로 옳지 않은 것은?',
 [('철이 부족하면 페리틴 mRNA의 3′ 말단 poly A 꼬리가 길어져 페리틴이 많이 번역된다','철 부족 → 5′ UTR에 단백질이 붙어 페리틴 번역 억제(옳지 않음)'),('초파리 난자의 모계 mRNA는 poly A 꼬리가 짧아 수정 전까지 번역되지 않는다','수정 후 꼬리가 길어지며 번역'),('5′ UTR에 조절 단백질이 결합하면 리보솜 결합이 막혀 번역량이 줄어든다','옳아요.'),('5′ 캡·poly A 꼬리·UTR 결합 단백질이 mRNA 안정성과 관련된다','옳아요.')],'',R1+['bio8:16'])
M('b8n10',P,U,1,'"환경이 유전자의 ON/OFF를 바꾼다"는 후성유전학에 대한 설명으로 옳은 것은?',
 [('DNA 염기서열은 바뀌지 않고 메틸화·히스톤 변형 같은 표지가 바뀌어 발현이 달라진다','유전자 자체는 그대로'),('환경이 DNA 염기서열을 바꾸는 돌연변이를 일으킨다','서열 변화가 아니에요.'),('후성유전적 표지는 세포 분열 시 절대 전달되지 않는다','유지 메틸화로 전달돼요.'),('일란성 쌍둥이는 후성유전적 표지도 평생 같다','환경에 따라 달라져요.')],'',R1)
M('b8n12',P,U,2,'DNA 복제 후 메틸화 유지에 대한 설명으로 옳은 것은?',
 [('복제 직후는 기존 가닥에만 표지가 남은 반메틸화 상태이며, 메틸화 효소가 새 가닥의 같은 위치(CpG)를 메틸화한다','DNA 중합효소: 서열 복제 / 메틸화 효소: 표지 유지'),('DNA 중합효소가 메틸화된 시토신을 그대로 복사한다','메틸기 없는 C로 복제돼요.'),('복제 직후 두 가닥 모두 메틸화되어 있다','기존 가닥만 → 반메틸화'),('메틸화 효소는 임의의 위치를 메틸화한다','기존 가닥과 같은 위치(CpG)예요.')],'',R1+['bio8:9'])
M('b8n14',P,U,2,'유전체 각인에 대한 설명으로 옳은 것은?',
 [('IGF2는 부계에서 온 대립유전자만 발현되며, 생식세포를 만들 때 메틸화 양상이 지워졌다가 성별에 따라 다시 새겨진다','필기 예시'),('부계와 모계 대립유전자가 항상 똑같이 발현된다','각인 유전자는 한쪽만 발현돼요.'),('각인은 염기서열이 바뀌는 돌연변이이다','메틸화(후성유전)예요.'),('DNA 메틸화 전체를 유전체 각인이라 한다','각인은 메틸화가 관여하는 현상 중 하나예요.')],'',R2+['bio8:10'])
M('b8n16',P,U,2,'히스톤 변형 표기 H3K9me3의 의미로 옳은 것은?',
 [('히스톤 H3의 9번째 아미노산인 라이신에 메틸기 3개가 붙음','→ HP1 결합 → 이질염색질 → 전사 억제'),('히스톤 H3의 9번째 아미노산인 라이신에 아세틸기 3개가 붙음','me = 메틸'),('히스톤 H9의 3번째 라이신에 메틸기 1개가 붙음','순서가 틀려요.'),('DNA의 9번째 시토신에 메틸기 3개가 붙음','히스톤 단백질 변형이에요.')],'',R2+['bio8:7'])
M('b8n17',P,U,2,'X 염색체 불활성화에 대한 설명으로 옳지 않은 것은?',
 [('Xist는 단백질로 번역되어 X 염색체를 분해한다','번역되지 않는 lncRNA(200 nt 이상)예요(옳지 않음).'),('불활성 X에서 전사된 Xist RNA가 그 X를 뒤덮고 메틸화·히스톤 변형으로 응축되어 바소체가 된다','시스로 작용'),('활성 X에서는 Tsix가 Xist와 상보적으로 결합해 억제한다','옳아요.'),('세포마다 무작위로 불활성화되어 암컷 삼색 고양이 털이 얼룩덜룩하다','암수 X 발현량을 맞추는 양적 조절')],'',R2+['bio8:11'])
M('b8n21',P,U,2,'miRNA의 생성과 작용 과정에 등장하는 단백질을 순서대로 바르게 나열한 것은?',
 [('드로샤(핵) → 다이서(세포질) → 아르고노트','pri → pre-miRNA → 이중 가닥 miRNA → 단일 가닥 + 아르고노트 복합체'),('다이서(핵) → 드로샤(세포질) → 아르고노트','장소가 반대예요.'),('아르고노트 → 드로샤 → 다이서','아르고노트는 마지막이에요.'),('드로샤(세포질) → 아르고노트(핵) → 다이서','틀려요.')],'',R2+['bio8:18'])
M('b8n27',P,U,2,'스플라이소솜과 스플라이싱에 대한 설명으로 옳은 것은?',
 [('snRNA와 단백질로 이루어진 스플라이소솜이 인트론 양 끝의 5′-GU … AG-3′을 인식하고, 잘려 나간 인트론은 올가미 구조를 이룬 뒤 분해된다','필기 내용'),('리보솜이 인트론을 잘라 낸다','스플라이소솜이에요.'),('인트론은 5′-AG … GU-3′로 시작하고 끝난다','GU로 시작해 AG로 끝나요.'),('잘려 나간 인트론은 단백질로 번역된다','분해돼요.')],'',R2+['bio8:14'])
M('b8n30',P,U,1,'유비퀴틴–프로테아솜 체계에 대한 설명으로 옳은 것은?',
 [('잘못 접힌 단백질 등에 유비퀴틴(수거자)이 붙으면 프로테아솜(소각자)이 아미노산으로 분해하고, 유비퀴틴은 떼어져 재사용된다','단백질의 수명 조절'),('프로테아솜은 mRNA를 분해한다','단백질을 분해해요.'),('유비퀴틴은 단백질과 함께 분해되어 사라진다','재사용돼요.'),('유비퀴틴이 붙으면 단백질이 활성화된다','분해 표지예요.')],'',R2+['bio8:22'])
U='세포 분화·발생'
M('b8n32',P,U,1,'Hox 유전자의 공선성이란?',
 [('Hox 유전자의 염색체 위 물리적 순서가 배아의 전후축(머리 → 꼬리)을 따라 발현되는 순서와 일치하는 것','생쥐에서도 유사'),('Hox 유전자가 모든 체절에서 같은 양으로 발현되는 것','위치별로 달라요.'),('Hox 유전자가 서로 다른 염색체에 무작위로 흩어져 있는 것','모여서 배열돼 있어요.'),('Antp와 Ubx가 같은 기능을 하는 것','Antp 다리, Ubx 평형곤'),],'',R3+['bio8:26'])
B('b8n36',P,U,3,'[ABC 모델 필기] 꽃의 호메오 유전자 a, b, c는 바깥쪽부터 (가) 꽃받침, (나) 꽃잎, (다) 수술, (라) 암술 영역에서 조합으로 발현되고, a와 c는 서로를 억제한다. 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
 [['(가) 영역에 c를 강제로 발현시키면 a가 억제되어 꽃받침이 생성되지 않는다.',True,'(가)는 c만 → 암술'],
  ['c를 결실시키면 a가 (다)·(라)까지 확장되어 (라)에 꽃받침이 생긴다.',True,'a만 → 꽃받침'],
  ['장미 같은 실제 꽃의 기관 형성은 a, b, c 세 유전자만으로 모두 설명된다.',False,'E 기능까지 필요해요.']],R3+['bio8:30'])
